<body>
<div class="wrap">
  <h1>Kvíz a Dunáról</h1>
  <p class="hint">10 kérdés · négy válaszlehetőség · a végén megkapod a pontszámod.</p>
  <main id="app"></main>
  <p class="sr-only" aria-live="polite" id="live"></p>
</div>
<script>
const QUESTIONS = [
  { q: "Hány országban folyik végig a Duna?", opts: ["7 ország", "10 ország", "3 ország", "12 ország"], a: 1 },
  { q: "Melyik városban torkollik a Duna a Fekete-tengerbe?", opts: ["Budapest", "Bécs", "Tulcea", "Belgrád"], a: 2 },
  { q: "Melyik a Duna leghosszabb magyarországi mellékfolyója?", opts: ["Rába", "Dráva", "Tisza", "Sajó"], a: 2 },
  { q: "Hány fővárost szel át a Duna?", opts: ["Kettőt", "Hármat", "Négyet", "Hatot"], a: 2 },
  { q: "Hány kilométer hosszú a Duna?", opts: ["Körülbelül 1800 km", "Körülbelül 2850 km", "Körülbelül 4200 km", "Körülbelül 550 km"], a: 1 },
  { q: "Melyik országból ered a Duna?", opts: ["Ausztria", "Svájc", "Németország", "Szlovákia"], a: 2 },
  { q: "Melyik tengerbe ömlik a Duna?", opts: ["Fekete-tenger", "Adria-tenger", "Északi-tenger", "Balti-tenger"], a: 0 },
  { q: "Melyik magyar város híres a Duna kanyarulatáról?", opts: ["Vác", "Visegrád", "Győr", "Pécs"], a: 1 },
  { q: "Melyik híres zenei művet írta Johann Strauss a Duna tiszteletére?", opts: ["A Duna-parti dalnok", "A kék Duna keringő", "Duna-szimfónia", "Duna-mazurka"], a: 1 },
  { q: "Melyik nem folyik a Dunába?", opts: ["Tisza", "Dráva", "Rába", "Zagyva"], a: 3 }
];

const app = document.getElementById('app');
const live = document.getElementById('live');
const KEY = 'duna-quiz-v1';
let state = { phase: 'intro', current: 0, answers: [] };

function announce(msg) { live.textContent = msg; }

function load() {
  if (window.alfy && window.alfy.storage) {
    window.alfy.storage.get(KEY).then(v => {
      if (v && typeof v === 'object' && Array.isArray(v.answers)) {
        state.phase = v.phase === 'done' ? 'done' : 'play';
        state.current = Math.min(Math.max(0, v.current | 0), QUESTIONS.length - 1);
        state.answers = v.answers.slice(0, QUESTIONS.length);
        render();
      }
    }).catch(() => {});
  }
}

function save() {
  if (window.alfy && window.alfy.storage) {
    window.alfy.storage.set(KEY, state).catch(() => {});
  }
}

function start() {
  state = { phase: 'play', current: 0, answers: [] };
  save(); render(); announce('A kvíz elkezdődött.');
}

function answer(i) {
  const c = state.current;
  if (state.answers[c] != null) return;
  state.answers[c] = i;
  save(); render();
}

function next() {
  if (state.current < QUESTIONS.length - 1) {
    state.current++; save(); render();
  } else {
    state.phase = 'done'; save(); render();
  }
}

function restart() {
  state = { phase: 'intro', current: 0, answers: [] };
  save(); render();
}

function render() {
  if (state.phase === 'intro') renderIntro();
  else if (state.phase === 'play') renderPlay();
  else renderDone();
}

function renderIntro() {
  app.innerHTML = `
    <div class="card">
      <h2 class="lead">Teszteld a tudásod a <strong>Dunáról</strong>!</h2>
      <p class="hint">10 kérdés vár rád, mindegyikhez négy válaszlehetőség tartozik. Válassz egyet, majd lépj tovább – a végén megmutatjuk a pontszámod és a helyes válaszokat.</p>
      <button class="btn primary" id="start">Kvíz indítása</button>
    </div>`;
  document.getElementById('start').addEventListener('click', start);
}

function renderPlay() {
  const c = state.current, item = QUESTIONS[c];
  const chosen = state.answers[c];
  const answered = chosen != null;
  const pct = Math.round((c / QUESTIONS.length) * 100);

  const opts = item.opts.map((text, i) => {
    let cls = 'opt', mark = '';
    if (answered) {
      if (i === item.a) { cls += ' correct'; mark = '✓'; }
      else if (i === chosen) { cls += ' wrong'; mark = '✗'; }
    } else if (i === chosen) {
      cls += ' sel'; mark = '•';
    }
    return `<button class="${cls}" data-i="${i}" ${answered ? 'disabled' : ''}><span class="mark" aria-hidden="true">${mark}</span><span>${text}</span></button>`;
  }).join('');

  const isLast = c === QUESTIONS.length - 1;
  const btnLabel = isLast ? 'Eredmény megtekintése' : 'Következő kérdés';
  const fb = answered ? (chosen === item.a ? 'Helyes válasz!' : 'Ez sajnos nem volt helyes.') : '';

  app.innerHTML = `
    <div class="card">
      <div class="bar"><div class="bar-fill" style="width:${pct}%"></div></div>
      <p class="counter">${c + 1}. kérdés a(z) ${QUESTIONS.length}-ből</p>
      <h2 class="q">${item.q}</h2>
      <div class="opts">${opts}</div>
      <p class="feedback ${answered && chosen === item.a ? 'ok' : ''}">${fb}</p>
      <div class="nav">
        <span></span>
        <button class="btn primary" id="next" ${answered ? '' : 'disabled'}>${btnLabel}</button>
      </div>
    </div>`;

  app.querySelectorAll('.opt').forEach(b => b.addEventListener('click', () => answer(+b.dataset.i)));
  document.getElementById('next').addEventListener('click', next);
}

function renderDone() {
  const score = QUESTIONS.reduce((s, it, i) => s + (state.answers[i] === it.a ? 1 : 0), 0);
  const total = QUESTIONS.length;
  let verdict;
  if (score >= 9) verdict = 'Kiváló – igazi Duna-szakértő vagy!';
  else if (score >= 7) verdict = 'Nagyon jól teljesítettél!';
  else if (score >= 5) verdict = 'Közepes eredmény – érdemes még egy kört!';
  else verdict = 'Kezdő vagy a Duna témában – próbáld újra!';

  const review = QUESTIONS.map((it, i) => {
    const chosen = state.answers[i];
    const ok = chosen === it.a;
    const miss = !ok && chosen != null ? ` <span class="miss">(téves: ${it.opts[chosen]})</span>` : '';
    return `<li><p class="rq">${i + 1}. ${it.q}</p><p class="ra">${ok ? '✓' : '✗'} Helyes: <b>${it.opts[it.a]}</b>${miss}</p></li>`;
  }).join('');

  app.innerHTML = `
    <div class="card">
      <h2 class="lead">Íme az eredményed</h2>
      <p class="score">${score}<small> / ${total}</small></p>
      <p class="verdict">${verdict}</p>
      <h3>Áttekintés</h3>
      <ul class="review">${review}</ul>
      <button class="btn primary" id="again">Újra kezdés</button>
    </div>`;
  document.getElementById('again').addEventListener('click', restart);
  announce(`A kvíz vége. Pontszám: ${score} a(z) ${total}-ből.`);
}

load();
render();
</script>
</body>
</html>
